            double val = ratio * i;
            a1 = (long) Math.floor(val);
            a2 = (long) Math.ceil(val);
            double diff1 = Math.abs(ratio - (double) a1 / i);
            if (diff1 < min_diff - epsilon) {
                min_diff = diff1;
                a = a1;
                b = i;
            }
            double diff2 = Math.abs((double) a2 / i - ratio);
            if (diff2 < min_diff - epsilon) {
                min_diff = diff2;
                a = a2;
                b = i;
            }
        }
        System.out.println(a + "/" + b);
        sc.close();
    }
